import itertools

def find_costas(n=12, fixed={3:8, 8:2}):
    # columns to assign in order
    cols = list(range(n))
    # we can order columns by most constrained? Let's just do natural order but maybe put fixed early.
    # Actually fixed are at 3 and 8, they will be assigned when we reach them.
    assigned = {}  # col -> row
    used_rows = set()

    # Precompute all pairs of columns that will have same dc? Not needed.

    # For pruning: store for each dc, the set of drs seen from fully assigned pairs.
    # When we add a new pair (a,c), we compute dc=c-a, dr=x[c]-x[a], and check if dr already present for that dc.
    vectors = {}  # dc -> set of dr

    # Let's assign recursively
    def backtrack(idx):
        if idx == n:
            # all columns assigned
            return [assigned[c] for c in range(n)]
        c = cols[idx]
        if c in fixed:
            # must assign fixed value
            r = fixed[c]
            if r in used_rows:
                return None
            # check constraints with all previously assigned columns a < c
            for a, ra in assigned.items():
                dc = c - a
                dr = r - ra
                if dc > 0:
                    if dc in vectors and dr in vectors[dc]:
                        return None
                else:
                    # a > c? But we assign in order of cols list, not necessarily column index.
                    # Actually assigned may contain columns > c if we assigned them earlier.
                    # We need to consider the pair with positive dc.
                    dc2 = a - c
                    dr2 = ra - r
                    if dc2 in vectors and dr2 in vectors[dc2]:
                        return None
            # commit
            assigned[c] = r
            used_rows.add(r)
            # add vectors
            added = []
            for a, ra in assigned.items():
                if a == c:
                    continue
                if c > a:
                    dc = c - a
                    dr = r - ra
                else:
                    dc = a - c
                    dr = ra - r
                # dr cannot be 0 because permutation
                if dc in vectors:
                    if dr in vectors[dc]:
                        # should not happen because checked above
                        pass
                    else:
                        vectors[dc].add(dr)
                        added.append((dc, dr))
                else:
                    vectors[dc] = {dr}
                    added.append((dc, dr))
            res = backtrack(idx+1)
            # revert
            for dc, dr in added:
                vectors[dc].remove(dr)
                if not vectors[dc]:
                    del vectors[dc]
            used_rows.remove(r)
            del assigned[c]
            return res
        else:
            # try possible rows
            # maybe order rows by some heuristic? Let's just try all unused rows.
            # But we can prune heavily.
            for r in range(n):
                if r in used_rows:
                    continue
                # quick check: for each assigned a, compute vector for pair (min(a,c), max(a,c))
                ok = True
                for a, ra in assigned.items():
                    if c > a:
                        dc = c - a
                        dr = r - ra
                    else:
                        dc = a - c
                        dr = ra - r
                    if dc in vectors and dr in vectors[dc]:
                        ok = False
                        break
                if not ok:
                    continue
                # commit
                assigned[c] = r
                used_rows.add(r)
                added = []
                for a, ra in assigned.items():
                    if a == c:
                        continue
                    if c > a:
                        dc = c - a
                        dr = r - ra
                    else:
                        dc = a - c
                        dr = ra - r
                    if dc in vectors:
                        vectors[dc].add(dr)
                    else:
                        vectors[dc] = {dr}
                    added.append((dc, dr))
                res = backtrack(idx+1)
                if res is not None:
                    return res
                # revert
                for dc, dr in added:
                    vectors[dc].remove(dr)
                    if not vectors[dc]:
                        del vectors[dc]
                used_rows.remove(r)
                del assigned[c]
            return None

    return backtrack(0)

